def build_guild_district_text(user_id):
    status = get_contract_status(user_id)
    text = f'📜 Гільдія Найманців

На старій дошці висять замовлення від варти, торговців і мандрівників. Тут беруть роботу ті, хто не боїться вийти за межі табору.

'
    if not status['exists']:
        text += '❌ Персонажа не знайдено.'
        return text
    if not status['unlocked']:
        text += f"🔒 Контракти відкриються з 5 рівня.
👤 Твій рівень: {status['level']}
"
        return text
    text += f"📆 Сьогодні здано контрактів: {status['completed_today']}/{status['daily_limit']}
"
    active = status['active_contract']
    if active:
        if active.get('completed'):
            text += f"
✅ Виконаний контракт очікує здачі:
🎯 Ціль: {active['target_mob_name']}
📈 Прогрес: {active['current_kills']}/{active['target_kills']}
✨ Нагорода: {active['reward_exp']} EXP

Зайди до дошки контрактів, щоб здати його."
        else:
            text += f"
📌 Активний контракт:
🎯 Ціль: {active['target_mob_name']}
📈 Прогрес: {active['current_kills']}/{active['target_kills']}
✨ Нагорода після здачі: {active['reward_exp']} EXP
"
    else:
        text += '
✅ Можна переглянути дошку контрактів.'
    return text

def get_nearby_mobs_for_level(player_level, location_id):
    mobs = get_mobs_for_location(location_id)
    available = []
    for mob in mobs:
        mob_level = int(mob.get('level', 1))
        min_player_level = int(mob.get('min_player_level', 1))
        if min_player_level <= player_level and player_level - 1 <= mob_level <= player_level + 1:
            available.append(mob)
    if not available:
        for mob in mobs:
            if int(mob.get('min_player_level', 1)) <= player_level:
                available.append(mob)
    return available

