        "bonus_int": "🔮 Інтелект",
        "bonus_wis": "🦉 Мудрість",
        "bonus_sta": "🛡 Витривалість",
        "pdef": "🛡 Фіз. захист",
        "mdef": "🔮 Маг. захист",
    }
