def accept_guild_application(actor_user_id, application_id):
    init_guild_system()

    app = get_guild_application_by_id(application_id)

    if not app:
        return {"success": False, "message": "❌ Заявку не знайдено."}

    guild_id = app["guild_id"]
    applicant_user_id = app["user_id"]

    applicant_level_gate = get_guild_access_level_state(applicant_user_id)
    if not applicant_level_gate.get("success"):
        _guild_safe_set_application_status(
            application_id,
            GUILD_APPLICATION_REJECTED,
            processed_by=actor_user_id,
        )
        return {
            "success": False,
            "message": (
                f"❌ Заявку відхилено: вступ доступний з {MIN_GUILD_ACCESS_LEVEL} рівня. "
                f"Поточний рівень гравця: {applicant_level_gate.get('level', 0)}."
            ),
        }

    if app["status"] != GUILD_APPLICATION_PENDING:
        return {"success": False, "message": "❌ Ця заявка вже не очікує розгляду."}

    if not can_manage_guild_applications(actor_user_id, guild_id):
        return {"success": False, "message": "❌ У тебе немає прав для обробки заявок."}

    guild = get_guild_by_id(guild_id)
    if not guild:
        return {"success": False, "message": "❌ Гільдію не знайдено."}

    applicant_name = get_character_name_by_user_id(applicant_user_id)
    existing_member = get_user_guild_member(applicant_user_id)

    # Idempotent recovery: гравець уже в цій гільдії, але pending-заявка висить.
    if existing_member and int(existing_member["guild_id"]) == int(guild_id):
        _guild_safe_set_application_status(
            application_id,
            GUILD_APPLICATION_ACCEPTED,
            processed_by=actor_user_id,
        )
        _guild_cancel_other_pending_applications(
            applicant_user_id,
            except_application_id=application_id,
            processed_by=actor_user_id,
        )
        return {
            "success": True,
            "message": f"✅ {applicant_name} уже перебуває в цій гільдії. Заявку очищено."
        }

    # Якщо гравець уже в іншій гільдії — pending-заявку треба прибрати без падіння.
    if existing_member and int(existing_member["guild_id"]) != int(guild_id):
        _guild_safe_set_application_status(
            application_id,
            GUILD_APPLICATION_REJECTED,
            processed_by=actor_user_id,
        )
        return {"success": False, "message": "❌ Гравець уже перебуває в іншій гільдії. Заявку відхилено."}

    member_count = get_guild_member_count(guild_id)
    member_limit = int(guild["member_limit"] or DEFAULT_GUILD_MEMBER_LIMIT)

    if member_count >= member_limit:
        return {"success": False, "message": "❌ У гільдії немає вільних місць."}

    now = now_iso()

    try:
        cursor.execute("""
        INSERT INTO guild_members (guild_id, user_id, role, joined_at)
        VALUES (?, ?, ?, ?)
        """, (
            guild_id,
            applicant_user_id,
            GUILD_ROLE_MEMBER,
            now,
        ))
        conn.commit()
    except Exception as error:
        # Якщо паралельно/раніше гравець уже був доданий — переводимо в idempotent branch.
        if "UNIQUE constraint failed" not in str(error):
            raise

    _guild_safe_set_application_status(
        application_id,
        GUILD_APPLICATION_ACCEPTED,
        processed_by=actor_user_id,
    )

    _guild_cancel_other_pending_applications(
        applicant_user_id,
        except_application_id=application_id,
        processed_by=actor_user_id,
    )

    try:
        add_guild_log(
            guild_id=guild_id,
            event_type="application_accepted",
            text=f"{applicant_name} вступив до гільдії."
        )
    except Exception:
        pass

    return {"success": True, "message": f"✅ {applicant_name} прийнято до гільдії."}

def calculate_guild_level_from_exp(total_exp):
    try:
        total_exp = int(total_exp or 0)
    except Exception:
        total_exp = 0

    level = 1

    while total_exp >= get_guild_exp_required_for_level(level + 1):
        level += 1

    return level

def recalculate_guild_level(guild_id):
    guild = get_guild_by_id(guild_id)

    if not guild:
        return None

    old_level = int(guild["level"] or 1)
    total_exp = int(guild["total_exp"] or 0)
    new_level = calculate_guild_level_from_exp(total_exp)

    if new_level != old_level:
        cursor.execute(
            "UPDATE guilds SET level=?, updated_at=? WHERE id=?",
            (new_level, now_iso(), guild_id)
        )
        conn.commit()

        if new_level > old_level:
            try:
                add_guild_log(
                    guild_id=guild_id,
                    event_type="guild_level_up",
                    text=f"Гільдія піднялась до рівня {new_level}."
                )
            except Exception:
                pass

    return new_level

def cleanup_recalculate_all_guild_levels():
    init_guild_system()
    cursor.execute("SELECT id FROM guilds")
    rows = cursor.fetchall()
    updated = 0

    for row in rows:
        try:
            guild_id = row["id"]
        except Exception:
            guild_id = row[0]
        old = get_guild_by_id(guild_id)["level"]
        new = recalculate_guild_level(guild_id)
        if new != old:
            updated += 1

    return updated

def create_guild_application(user_id, guild_id):
    """
    FINAL OVERRIDE:
    Подача заявки з журналом через character_name замість user_id.
    """

    init_guild_system()
    level_gate = get_guild_access_level_state(user_id)
    if not level_gate.get("success"):
        return {
            "success": False,
            "message": (
                f"❌ Вступ до гільдії доступний з {MIN_GUILD_ACCESS_LEVEL} рівня.\n"
                f"Твій поточний рівень: {level_gate.get('level', 0)}."
            ),
        }

    gate = can_user_join_or_create_guild(user_id)
    if not gate.get("success"):
        return gate

    if is_user_in_guild(user_id):
        return {
            "success": False,
            "message": "❌ Ти вже перебуваєш у гільдії."
        }

    guild = get_guild_by_id(guild_id)

    if not guild:
        return {
            "success": False,
            "message": "❌ Гільдію не знайдено."
        }

    cursor.execute("""
    SELECT * FROM guild_applications
    WHERE guild_id=? AND user_id=? AND status=?
    """, (
        guild_id,
        user_id,
        GUILD_APPLICATION_PENDING,
    ))

    if cursor.fetchone():
        return {
            "success": False,
            "message": "ℹ️ Ти вже подав заявку в цю гільдію."
        }

    cursor.execute("""
    INSERT INTO guild_applications (guild_id, user_id, status, created_at)
    VALUES (?, ?, ?, ?)
    """, (
        guild_id,
        user_id,
        GUILD_APPLICATION_PENDING,
        now_iso(),
    ))

    conn.commit()

    applicant_name = get_character_name_by_user_id(user_id)

    add_guild_log(
        guild_id=guild_id,
        event_type="application_created",
        text=f"Нова заявка до гільдії від {applicant_name}."
    )

    return {
        "success": True,
        "message": "✅ Заявку до гільдії подано."
    }

def run_guild_sanity_cleanup():
    """
    Conservative cleanup used by /guild_fix_states and startup-compatible calls:
    - stale pending applications for players already in guilds;
    - guild levels recalculation;
    - duplicate icon/index checks if available.
    """

    result = {
        "stale_applications": None,
        "levels_recalculated": None,
        "icons_checked": False,
        "ok": True,
        "errors": [],
    }

    try:
        try:
            result["stale_applications"] = cleanup_stale_guild_applications()
        except Exception as error:
            result["errors"].append(f"cleanup_stale_guild_applications: {error}")

        try:
            result["levels_recalculated"] = cleanup_recalculate_all_guild_levels()
        except Exception as error:
            result["errors"].append(f"cleanup_recalculate_all_guild_levels: {error}")

        try:
            ensure_unique_guild_icon_index()
            result["icons_checked"] = True
        except Exception as error:
            result["errors"].append(f"ensure_unique_guild_icon_index: {error}")

    except Exception as error:
        result["ok"] = False
        result["errors"].append(str(error))

    if result["errors"]:
        result["ok"] = False

    return result

def init_item_id_allocator_system(db_path=None, conn=None):
    own=conn is None
    if own: conn=sqlite3.connect(db_path or "game.db")
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS item_id_allocator(
            namespace TEXT PRIMARY KEY,last_issued_id INTEGER NOT NULL,
            range_min INTEGER NOT NULL,range_max INTEGER NOT NULL,
            updated_at TEXT NOT NULL)""")
        conn.execute("""CREATE TABLE IF NOT EXISTS generated_item_id_migrations(
            id INTEGER PRIMARY KEY AUTOINCREMENT,source_item_id INTEGER NOT NULL,
            target_item_id INTEGER NOT NULL UNIQUE,operation TEXT NOT NULL,
            migration_stage TEXT NOT NULL,created_at TEXT NOT NULL,
            UNIQUE(source_item_id,target_item_id,operation))""")
        now=datetime.now(timezone.utc).isoformat()
        permanent_max=conn.execute("SELECT COALESCE(MAX(id),?) FROM items WHERE is_generated=1 AND shop_preview_owner IS NULL AND COALESCE(shop_preview_price,0)=0 AND id BETWEEN ? AND ?",(PRIMARY_MIN-1,PRIMARY_MIN,OVERFLOW_MAX)).fetchone()[0]
        preview_max=conn.execute("SELECT COALESCE(MAX(id),?) FROM items WHERE (shop_preview_owner IS NOT NULL OR COALESCE(shop_preview_price,0)>0) AND id BETWEEN ? AND ?",(PREVIEW_MIN-1,PREVIEW_MIN,PREVIEW_MAX)).fetchone()[0]
        conn.execute("INSERT OR IGNORE INTO item_id_allocator(namespace,last_issued_id,range_min,range_max,updated_at) VALUES(?,?,?,?,?)",(PERMANENT_NAMESPACE,max(PRIMARY_MIN-1,int(permanent_max)),PRIMARY_MIN,OVERFLOW_MAX,now))
        conn.execute("INSERT OR IGNORE INTO item_id_allocator(namespace,last_issued_id,range_min,range_max,updated_at) VALUES(?,?,?,?,?)",(PREVIEW_NAMESPACE,max(PREVIEW_MIN-1,int(preview_max)),PREVIEW_MIN,PREVIEW_MAX,now))
        if own: conn.commit()
        return {"success":True}
    finally:
        if own: conn.close()

def recover_stranded_preview_item(conn,source_item_id):
    """Move an already-purchased item out of preview namespace atomically."""
    source_item_id=int(source_item_id)
    row=conn.execute("SELECT * FROM items WHERE id=? AND shop_preview_owner IS NULL AND COALESCE(shop_preview_price,0)=0",(source_item_id,)).fetchone()
    if not row: raise RuntimeError("Stranded preview item not found")
    columns=[str(r[1]) for r in conn.execute("PRAGMA table_info(items)")]
    target=allocate_generated_item_id(conn)
    values=list(row); values[columns.index("id")]=target
    conn.execute("INSERT INTO items("+",".join('"'+c+'"' for c in columns)+") VALUES("+",".join('?' for _ in columns)+")",values)
    reference_columns=(("auction_lots","item_ref_id"),("character_name_changes","item_id"),("crystal_shop_purchases","item_id"),("inventory","item_id"),("inventory_runes","rune_item_id"),("player_trade_offers","item_id"),("premium_item_grants","item_id"),("refine_attempts","item_id"))
    for table,column in reference_columns:
        known={str(r[1]) for r in conn.execute('PRAGMA table_info("'+table+'")')}
        if column in known: conn.execute(f'UPDATE "{table}" SET "{column}"=? WHERE "{column}"=?',(target,source_item_id))
    record_item_id_mapping(conn,source_item_id,target,"shop_preview_purchase_recovery","18.1.9b")
    conn.execute("DELETE FROM items WHERE id=?",(source_item_id,))
    return target

def try_claim_pending_items(db, user_id):

    from db_modules.inventory import add_item



    small_hp, small_mp, stones, medium_hp, medium_mp = _pending_item_totals(db, user_id)

    quantities = (

        (SMALL_HEALTH_POTION_ITEM_ID, small_hp),

        (SMALL_MANA_POTION_ITEM_ID, small_mp),

        (REFINE_STONE_ITEM_ID, stones),

        (MEDIUM_HEALTH_POTION_ITEM_ID, medium_hp),

        (MEDIUM_MANA_POTION_ITEM_ID, medium_mp),

    )

    if not any(quantity > 0 for _item_id, quantity in quantities):

        return {"success": True, "pending": False}



    savepoint = "rom_level_up_reward_items_17_14_1_2"

    db.cursor.execute(f"SAVEPOINT {savepoint}")

    try:

        for item_id, quantity in quantities:

            if quantity <= 0:

                continue

            result = add_item(user_id, item_id, quantity, commit=False)

            if not result.get("success"):

                raise RuntimeError(result.get("message") or f"item {item_id} delivery failed")

        db.cursor.execute(

            """UPDATE level_up_rewards

                  SET items_claimed=1, items_claimed_at=?

                WHERE user_id=? AND items_claimed=0""",

            (datetime.now().isoformat(), int(user_id)),

        )

        db.cursor.execute(f"RELEASE {savepoint}")

        return {

            "success": True, "pending": False,

            "small_health_potions": small_hp, "small_mana_potions": small_mp,

            "refine_stones": stones, "medium_health_potions": medium_hp,

            "medium_mana_potions": medium_mp,

        }

    except Exception as error:

        db.cursor.execute(f"ROLLBACK TO {savepoint}")

        db.cursor.execute(f"RELEASE {savepoint}")

        return {"success": False, "pending": True, "message": str(error)}

def apply_level_up_rewards_in_transaction(db, user_id, old_level, new_level):

    plan = calculate_level_rewards(old_level, new_level)

    gold, inserted_levels = _insert_new_reward_rows(db, user_id, plan)

    item_result = try_claim_pending_items(db, user_id)

    return {**plan, "gold_awarded_now": gold, "new_ledger_levels": inserted_levels, "item_result": item_result}

