        selected=[x for x in _TRADE_PREVIEW_ITEM_FIELDS_12_6_3 if x in columns]
        if selected:
            sql="SELECT "+",".join('"'+x+'"' for x in selected)+" FROM items WHERE id=?"
            row=conn.execute(sql,(int(snapshot["item_id"]),)).fetchone()
